local DreamAdventuresTaskCell = Class("DreamAdventuresTaskCell")

--region lifecycle
function DreamAdventuresTaskCell:__init()
    self.type = TYPE.TASK
end

function DreamAdventuresTaskCell:__delete()
    self.type = nil
end

function DreamAdventuresTaskCell:Awake()
    self:InitHandler()
end

function DreamAdventuresTaskCell:Start()

end

function DreamAdventuresTaskCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function DreamAdventuresTaskCell:InitHandler()
    SetButtonAction(self.FontStyleButton, Bind(self, self.BtnOnClickHandler))
end
--endregion init

--region handler
---按钮点击回调
function DreamAdventuresTaskCell:BtnOnClickHandler()
    if self._isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end

    if self._isCanDraw and not self._isDraw then
        -- 领取
        Events.Broadcast(Constants.EventNames.DreamAdventuresTaskDraw, self._taskInfo.id)
    else
        -- 前往
        if checkNumber(self._taskInfo.openType) > 0 then
            local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self._taskInfo.openType)
            local t = checkTable(CfUtils.Split(self._taskInfo.openParameter))
            GoodsConfMgr:GetInstance():ExecuteJump(row, nil, nil, nil, t)
        end
    end
end
--endregion handler

--region public
---刷新
function DreamAdventuresTaskCell:Refresh(taskInfo, type)
    self._taskInfo = taskInfo
    self.type = checkNumber(type)
    if isNull(self._taskInfo) then
        return
    end
    self._isCanDraw = checkBool(taskInfo.status == 1)
    self._isDraw = checkBool(taskInfo.status == 2)
    self._isUnderWay = checkBool(taskInfo.status == 99)
    self:RefreshUI()
end
--endregion public

--region private
---刷新UI
function DreamAdventuresTaskCell:RefreshUI()
    CfUtils.SetUISwitchImage(self.BgTexture2, self._isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.BgTexture1, self._isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgDecorate, self._isCanDraw and 2 or 1)
    --CfUtils.SetUISwitchImage(self.ImgREN, self._isDraw and 2 or 1)

    if self.type == TYPE.TASK then
        CfUtils.FillText(self.NameTxt, checkString(self._taskInfo.desc, { _target_num_ = self._taskInfo.targetNum }))
        CfUtils.FillText(self.TitleText, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", { _num1_ = self._taskInfo.progress, _num2_ = self._taskInfo.targetNum }))
        self.Slider.value = checkNumber(self._taskInfo.progress) / checkNumber(self._taskInfo.targetNum)
        CfUtils.SetActive(self.HasReceived, self._isDraw)
        CfUtils.SetActive(self.TextUnderway, self._isUnderWay)
    else
        local vo = DreamAdventuresMgr:GetScheduleVo()
        if vo then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.storeCornId)
            if isNotNull(goodsVo) then
                CfUtils.FillImage(self.ImgIconActivity, goodsVo.photoPath)
            end
        end
        CfUtils.FillText(self.TextDescribe, checkString(self._taskInfo.desc, { _target_num_ = self._taskInfo.targetNum }))
        CfUtils.SetUISwitchImage(self.FIll, self._isCanDraw and 2 or 1)
        CfUtils.SetSliderPercent(self.SliderComplete,  checkNumber(self._taskInfo.progress) / checkNumber(self._taskInfo.targetNum))
        CfUtils.FillText(self.TxtReward, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", { _num1_ = self._taskInfo.progress, _num2_ = self._taskInfo.targetNum }))
        CfUtils.SetActive(self.Complete, self._isDraw)
        CfUtils.SetActive(self.Underway, self._isUnderWay)
    end

    CfUtils.SetActive(self.FontStyleButton, not self._isDraw and not self._isUnderWay)
    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))
    if self._isCanDraw and not self._isDraw then
        fontStyleBtn:ResetFontStyle("B12", localize("领取"))
    else
        fontStyleBtn:ResetFontStyle("B13", localize("前往"))
    end


    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsListLight")
    if isNull(scr) then
        scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    end
    scr:FreshBaseUI(self._taskInfo.rewards)
end
--endregion private

return DreamAdventuresTaskCell